package main
import("encoding/json";"os";"sort";"go-stock/backend/analysis/candlepattern")
type Row struct{Date string `json:"date"`;ShortCode string `json:"short_code"`;Pattern string `json:"pattern"`;PnL float64 `json:"pnl"`}
type Bar struct{Date string `json:"date"`;Open float64 `json:"open"`;Close float64 `json:"close"`;High float64 `json:"high"`;Low float64 `json:"low"`}
type Out struct{Date string `json:"date"`;Pattern string `json:"pattern"`;PnL float64 `json:"pnl"`;Code string `json:"code"`;Name string `json:"name"`;Bars []Bar `json:"bars"`}
func main(){var raw struct{Rows []Row `json:"rows"`};f,_:=os.Open(".cowork-temp/t0-observations-2025-2026.json");json.NewDecoder(f).Decode(&raw);f.Close();root,_:=candlepattern.ResolveCacheRoot(".");var out []Out;for _,r:=range raw.Rows{if r.Pattern!="DYIN|YX|MYIN"&&r.Pattern!="ZT|DYIN|DT"{continue};c,e:=candlepattern.LoadDailyCache(root,r.Date);if e!=nil{panic(e)};meta:=candlepattern.StockMeta{};for _,x:=range c.Stocks{if x.ShortCode==r.ShortCode{meta=x;break}};bars:=c.Daily[r.ShortCode];start:=len(bars)-10;if start<0{start=0};o:=Out{r.Date,r.Pattern,r.PnL,r.ShortCode,meta.Name,nil};for _,b:=range bars[start:]{o.Bars=append(o.Bars,Bar{b.Date,b.Open,b.Close,b.High,b.Low})};out=append(out,o)};sort.Slice(out,func(i,j int)bool{if out[i].Date==out[j].Date{return out[i].Code<out[j].Code};return out[i].Date<out[j].Date});json.NewEncoder(os.Stdout).Encode(out)}
